from django.db import migrations, models


def mark_area_answered(apps, schema_editor):
    """The setup is now type, budget, area. Alerts made before could already set an area (or not, which meant
    everywhere), so area counts as answered for them and they stay complete."""
    HomeAlert = apps.get_model("home", "HomeAlert")
    for alert in HomeAlert.objects.all():
        answered = set(alert.answered or [])
        if "area" not in answered:
            alert.answered = sorted(answered | {"area"})
            alert.save(update_fields=["answered"])


